INSERT INTO `documents` VALUES (1,'DOC01','Sách Giáo Lý Khối Khai Tâm (Bản Chuẩn GP. Phú Cường)','Giáo Trình','PDF','Khối Khai Tâm (Lớp Dự Bị, KT1, KT2)','4.2 MB','Ủy Ban Giáo Lý GP Phú Cường',320,'Giáo trình tranh ảnh đầy đủ màu sắc dành cho các em 6-8 tuổi bắt đầu làm quen với Chúa Giêsu, lời cầu nguyện và các nhân vật Kinh Thánh.','Tài liệu gồm 24 bài học căn bản về Thiên Chúa Tình Yêu, Chúa Giêsu Bạn Của Trẻ Thơ, Đức Mẹ Maria và những kinh nguyện đầu đời.',NULL,'2026-08-29 23:54:32','2026-08-29 23:54:32'),(2,'DOC02','Sách Giáo Lý Đến Bàn Tiệc Thánh - Khối Rước Lễ','Giáo Trình','PDF','Khối Rước Lễ (RL1, RL2, RL3)','5.8 MB','Ủy Ban Giáo Lý Đức Tin',415,'Tài liệu chuẩn bị tâm hồn cho các em xưng tội và rước lễ lần đầu, gồm các bí tích Hòa Giải và Thánh Thể.','Tài liệu gồm 30 bài học chuyên sâu về Bí Tích Hòa Giải, Bí Tích Thánh Thể, 10 Điều Răn và 6 Điều Răn Hội Thánh.',NULL,'2026-08-29 23:54:32','2026-08-29 23:54:32'),(3,'DOC03','Sách Giáo Lý Lớn Lên Trong Chúa Thánh Thần - Khối Thêm Sức','Giáo Trình','PDF','Khối Thêm Sức (TS1, TS2, TS3)','6.1 MB','Ủy Ban Giáo Lý Đức Tin',380,'Giáo trình bồi dưỡng đức tin và 7 ơn Chúa Thánh Thần giúp các em sẵn sàng lãnh nhận Bí tích Thêm Sức.','Gồm 32 bài học về Chúa Thánh Thần, Hội Thánh, Phụng Vụ, 7 Ơn Chúa Thánh Thần và Đời Sống Đức Tin Trưởng Thành.',NULL,'2026-08-29 23:54:32','2026-08-29 23:54:32'),(4,'DOC04','Sách Giáo Lý Sống Đạo Giữa Đời - Khối Bao Đồng','Giáo Trình','PDF','Khối Bao Đồng (BD1, BD2, BD3)','7.0 MB','Ủy Ban Giáo Lý GP Phú Cường',290,'Giáo trình tuyên xưng đức tin, sống đạo và đối thoại giữa người Kitô hữu trong xã hội hiện đại.','Gồm 36 bài học về Luân Lý Công Giáo, Nhân Bản Kitô Giáo, Lương Tâm, Tội Lỗi và Ơn Cứu Độ.',NULL,'2026-08-29 23:54:32','2026-08-29 23:54:32'),(5,'DOC05','Sách Giáo Lý Hành Trang Vào Đời - Khối Vào Đời','Giáo Trình','PDF','Khối Vào Đời (VD1, VD2)','6.5 MB','Ủy Ban Giáo Lý Đức Tin',260,'Hành trang định hướng ơn gọi, hôn nhân gia đình, đạo đức nghề nghiệp và sứ vụ tông đồ giáo dân.','Gồm 28 bài học định hướng tương lai, tình yêu - hôn nhân Kitô giáo, trách nhiệm xã hội và ơn gọi đời sống.',NULL,'2026-08-29 23:54:32','2026-08-29 23:54:32'),(6,'DOC06','Nội Quy & Sổ Tay Huynh Trưởng Thiếu Nhi Thánh Thể VN','Sổ Tay','PDF','Dành Cho GLV & Huynh Trưởng','3.5 MB','Tổng Liên Đoàn TNTT Việt Nam',510,'Cẩm nang toàn diện về phương pháp tự nhiên, siêu nhiên, hiệu lệnh còi cờ, nghi thức chào cờ và linh đạo TNTT.','Quy định đầy đủ về đồng phục, cấp bậc, nghi thức tuyên hứa, quản lý đoàn sinh và điều hành sa mạc huấn luyện.',NULL,'2026-08-29 23:54:32','2026-08-29 23:54:32'),(7,'DOC07','Sổ Tay Kỹ Năng & Trò Chơi Sinh Hoạt Thiếu Nhi','Sổ Tay','DOCX','Dành Cho GLV Đứng Lớp','2.1 MB','Ban Kỹ Năng Xứ Đoàn Tân Mỹ',440,'Tổng hợp hơn 150 trò chơi vòng tròn, băng reo, trò chơi Kinh Thánh, gút dây và mật thư ứng dụng.','Bộ sưu tập trò chơi sinh hoạt giáo lý theo từng chủ đề bài học, giúp giờ học luôn hào hứng và sôi nổi.',NULL,'2026-08-29 23:54:32','2026-08-29 23:54:32'),(8,'DOC08','Tuyển Tập Bài Hát Sinh Hoạt & Nghi Thức TNTT (Có Hợp Âm)','Kinh & Hát','MP3','Toàn Đoàn Thiếu Nhi & GLV','12.8 MB','Ban Âm Nhạc TNTT',680,'Tuyển tập 50 bài hát sinh hoạt, bài ca chính thức của các ngành Ấu, Thiếu, Nghĩa và Huynh Trưởng.','Bao gồm file nghe MP3 chất lượng cao và lời bài hát kèm hợp âm guitar/organ đệm hát trong giờ chào cờ và sinh hoạt.',NULL,'2026-08-29 23:54:32','2026-08-29 23:54:32'),(9,'DOC09','Kinh Nguyện Hằng Ngày Dành Cho Thiếu Nhi Thánh Thể','Kinh & Hát','PDF','Toàn Thể Thiếu Nhi','1.5 MB','Ban Phụng Vụ Tân Mỹ',590,'Bản in bỏ túi các kinh nguyện sáng tối, kinh dâng ngày, kinh viếng Chúa, kinh dâng hoa và kinh bổn mạng.','Lời kinh chữ to, rõ ràng, dễ nhớ, có hình minh họa sinh động dành cho các em thiếu nhi học thuộc.',NULL,'2026-08-29 23:54:32','2026-08-29 23:54:32'),(10,'DOC10','Biểu Mẫu Sổ Điểm Điện Tử & Bảng Điểm Lớp Giáo Lý 2026 - 2027','Biểu Mẫu','XLSX','Giáo Lý Viên & Ban Học Vụ','1.2 MB','Ban Công Nghệ - Tân Mỹ',350,'Mẫu bảng tính Excel chuẩn gồm đầy đủ 3 Sheet: Học Kỳ 1, Học Kỳ 2, Tổng Kết Cả Năm có tích hợp sẵn công thức tính điểm trung bình và xếp loại.','Biểu mẫu sẵn sàng nạp trực tiếp vào hệ thống web qua chức năng \"Nhập Excel\" của Sổ Điểm Điện Tử.',NULL,'2026-08-29 23:54:32','2026-08-29 23:54:32');
/*!40000 ALTER TABLE `documents` ENABLE KEYS */;
UNLOCK TABLES;

