INSERT INTO `news` VALUES (1,'NEWS01','Lễ Khai Giảng Đoàn TNTT Giáo Xứ Tân Mỹ Năm Học 2026 - 2027','Khẩn','26/08/2026','Ban Quản Trị Xứ Đoàn','Ban Giáo Lý kính gửi quý phụ huynh và các em thiếu nhi toàn đoàn thời gian tập trung khai giảng, chương trình Thánh lễ tạ ơn và dặn dò đồng phục chuẩn TNTT.','Kính gửi: Quý Phụ Huynh, Anh Chị Huynh Trưởng và các em Thiếu Nhi toàn đoàn.\n\nNhằm chuẩn bị chu đáo cho niên khóa Giáo lý mới 2026 - 2027, Ban Quản Trị Đoàn Thiếu Nhi Thánh Thể Giáo xứ Tân Mỹ xin thông báo chương trình Lễ Khai Giảng như sau:\n\n1. Thời gian tập trung: 06h30 Chúa Nhật, ngày 06/09/2026 tại khuôn viên Giáo xứ.\n2. Thánh Lễ Tạ Ơn & Khai Giảng: 07h00 - 08h30 do Cha Tuyên Úy chủ tế.\n3. Quy định trang phục: Đồng phục Thiếu Nhi Thánh Thể chỉnh tề (áo trắng có huy hiệu, khăn quàng đúng ngành, quần sẫm màu).\n4. Sinh hoạt nhận lớp: Ngay sau Thánh lễ, các em sẽ di chuyển về các phòng học Giáo lý tương ứng theo sơ đồ hướng dẫn của Huynh Trưởng phụ trách.\n\nKính mong quý phụ huynh nhắc nhở và đưa đón các em đúng giờ để buổi lễ diễn ra trang nghiêm và sốt sắng.',1,'2026-08-29 23:54:32','2026-08-30 00:50:17'),(2,'NEWS02','Lịch Phân Công Huynh Trưởng - Giáo Lý Viên Đứng Lớp Năm Học 2026 - 2027','GLV','24/08/2026','Cha Tuyên Úy & Ban Điều Hành','Công bố quyết định phân công phụ trách giảng dạy cho 41 Anh Chị Huynh Trưởng & GLV tại 14 lớp thuộc 5 khối Giáo Lý.','Quyết định phân công nhiệm vụ giảng dạy Giáo lý niên khóa 2026 - 2027:\n\n- Tổng số GLV đứng lớp: 41 Huynh Trưởng & GLV.\n- Khối Khai Tâm (Dự Bị, KT1, KT2): 8 GLV phụ trách.\n- Khối Rước Lễ (RL1, RL2, RL3): 9 GLV phụ trách.\n- Khối Thêm Sức (TS1, TS2, TS3): 9 GLV phụ trách.\n- Khối Bao Đồng (BD1, BD2, BD3): 9 GLV phụ trách.\n- Khối Vào Đời (VD1, VD2): 6 GLV phụ trách.\n\nKính mời quý Anh Chị GLV kiểm tra thông tin phân công chi tiết tại mục \"Lớp Giáo Lý\" và \"Giáo Lý Viên\" trên cổng thông tin này.',0,'2026-08-29 23:54:32','2026-08-29 23:54:32'),(3,'NEWS03','Quy Định Về Giờ Lễ Thứ 5 và Lễ Chúa Nhật Của Thiếu Nhi','Lịch Lễ','20/08/2026','Ban Phụng Vụ Xứ Đoàn','Thông báo chi tiết thời gian sinh hoạt, tham dự Thánh lễ Thứ 5 và Chúa Nhật dành cho tất cả các ngành Chiên Con, Ấu Nhi, Thiếu Nhi, Nghĩa Sĩ.','Lịch Phụng Vụ & Sinh Hoạt Cố Định Hằng Tuần:\n\n1. Thánh Lễ Chiều Thứ 5:\n   - Tập trung & điểm danh: 17h45 tại nhà thờ.\n   - Thánh Lễ: 18h00 - 18h45.\n\n2. Thánh Lễ & Học Giáo Lý Chúa Nhật:\n   - Tập trung chào cờ TNTT: 06h45.\n   - Thánh Lễ Thiếu Nhi: 07h00 - 08h00.\n   - Giờ học Giáo Lý: 08h15 - 09h30.\n\nĐiểm chuyên cần tham dự Lễ Thứ 5, Lễ Chúa Nhật và Giờ học Giáo lý sẽ được tính trực tiếp vào Sổ Điểm Điện Tử của từng em.',0,'2026-08-29 23:54:32','2026-08-29 23:54:32');
/*!40000 ALTER TABLE `news` ENABLE KEYS */;
UNLOCK TABLES;

